// ========== 1. 原生 autoUpdater (基础) main.js ==========
const { app, autoUpdater, dialog } = require('electron')

// 配置更新服务器地址
// 服务器需要返回正确格式的更新元数据
const updateServer = 'https://your-update-server.com/updates/latest'

autoUpdater.setFeedURL({
  url: updateServer
})

// 检查更新
function checkForUpdates() {
  autoUpdater.checkForUpdates()
}

// ========== 2. autoUpdater 事件 ==========
// 正在检查更新
autoUpdater.on('checking-for-update', () => {
  console.log('正在检查更新...')
})

// 发现新版本
autoUpdater.on('update-available', (info) => {
  console.log('发现新版本:', info.version)
  console.log('发布日期:', info.releaseDate)
  // 可以通知用户
})

// 当前已是最新版本
autoUpdater.on('update-not-available', (info) => {
  console.log('当前已是最新版本')
})

// 正在下载更新
autoUpdater.on('update-downloading', (event) => {
  console.log('正在下载更新...')
  console.log('进度:', event.percent)
})

// 更新下载完成
autoUpdater.on('update-downloaded', (event) => {
  console.log('更新已下载完成')
  console.log('版本:', event.version)

  // 询问用户是否立即更新
  const dialogOpts = {
    type: 'info',
    buttons: ['立即重启', '稍后'],
    title: '应用更新',
    message: `新版本 ${event.version} 已下载完成`,
    detail: '点击"立即重启"安装更新'
  }

  dialog.showMessageBox(dialogOpts).then((returnValue) => {
    if (returnValue.response === 0) {
      // 退出并安装更新
      autoUpdater.quitAndInstall()
    }
  })
})

// 更新出错
autoUpdater.on('error', (error) => {
  console.error('更新出错:', error.message)
})

