// ========== 8. 手动更新检查 ==========
function manualUpdateCheck() {
  // 启动时检查
  app.whenReady().then(() => {
    mainWindow = new BrowserWindow({
      width: 800,
      height: 600,
      webPreferences: {
        preload: 'preload.js',
        contextIsolation: true
      }
    })
    mainWindow.loadFile('index.html')

    // 延迟一会儿再检查（避免影响启动速度）
    setTimeout(() => {
      checkForUpdates()
    }, 3000)
  })
}

